  ctx.fillStyle='#6b4733';ctx.fillRect(2,h-6,w*.7,6);ctx.fillStyle='#dbb475';ctx.fillRect(8,0,5,h-4);ctx.strokeRect(8,0,5,h-4);ctx.fillStyle='#ef454f';ctx.beginPath();ctx.moveTo(14,4);ctx.lineTo(w-2,16);ctx.lineTo(14,32);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#f9ce61';ctx.fillRect(8,-3,6,6);
